from PyPDF2 import PdfReader

pdf_path = '/home/ctfplayer/ctf_files/SPBlock_Email.pdf'
reader = PdfReader(pdf_path)
for page_idx, page in enumerate(reader.pages):
    print(f'--- Page {page_idx+1} ---')
    if '/Contents' in page:
        content = page['/Contents']
        try:
            # If content is an array
            if isinstance(content, list):
                for obj in content:
                    extracted = obj.get_data()
                    print(extracted[:400])
            else:
                # Sometimes a single content stream
                extracted = content.get_data()
                print(extracted[:400])
        except Exception as e:
            print(f'Error extracting stream: {e}')
    else:
        print('[NO /Contents IN PAGE]')

